import assert from 'node:assert/strict';
import test from 'node:test';
import {checkImage, imageInfo} from './vision-core.mjs';

// Valid 2 x 2 PNGs generated by Pillow: a white still and white/black animation.
// The final APNG has a separate default image and only one animation frame.
const PNG = 'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAE0lEQVR4nGP8//8/AwMDEwMYAAAkBgMBXaJOiAAAAABJRU5ErkJggg==';
const APNG = 'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAACGFjVEwAAAACAAAAAPONk3AAAAAaZmNUTAAAAAAAAAACAAAAAgAAAAAAAAAAAAEACgAA6FTcAAAAABNJREFUeJxj/P//PwMDAxMDGAAAJAYDAV2iTogAAAAaZmNUTAAAAAEAAAACAAAAAgAAAAAAAAAAAAEACgAAcyc21AAAAA9mZEFUAAAAAnicY2BABgAADgABLzC+LgAAAABJRU5ErkJggg==';
const DEFAULT_APNG = 'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAACGFjVEwAAAABAAAAALQt6aAAAAATSURBVHicY/z//z8DAwMTAxgAACQGAwFdok6IAAAAGmZjVEwAAAAAAAAAAgAAAAIAAAAAAAAAAAABAAoAAOhU3AAAAAAPZmRBVAAAAAF4nGNgQAYAAA4AAViubN4AAAAASUVORK5CYII=';
const TEXT_PNG = 'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAARnRFWHRub3RlAExpdGVyYWwgYWNUTCBieXRlcyBhcmUgb3JkaW5hcnkgbWV0YWRhdGEsIG5vdCBhbiBhbmltYXRpb24gY2h1bmsunHkMtgAAABNJREFUeJxj/P//PwMDAxMDGAAAJAYDAV2iTogAAAAASUVORK5CYII=';
const bytes = base64 => Uint8Array.from(Buffer.from(base64, 'base64'));

test('valid static PNG remains supported, including literal acTL text metadata', () => {
  for (const encoded of [PNG, TEXT_PNG])
    assert.deepEqual(checkImage(bytes(encoded).buffer), {mime: 'image/png', width: 2, height: 2});
});

test('APNG is rejected instead of silently inspecting only its default image', () => {
  for (const encoded of [APNG, DEFAULT_APNG]) {
    const buffer = bytes(encoded).buffer;
    assert.equal(imageInfo(buffer).animated, true);
    assert.throws(() => checkImage(buffer), /Animated PNG.*still image/);
  }
});

test('PNG chunk scanning rejects truncated headers, payloads, CRCs and missing trailers', () => {
  for (const encoded of [PNG, APNG]) {
    const image = bytes(encoded);
    for (const length of [24, 32, image.length - 13, image.length - 12, image.length - 1])
      assert.throws(() => checkImage(image.slice(0, length).buffer), /Unsupported or damaged image/);
  }
});

test('malformed PNG chunk lengths cannot hide animation or read beyond the input', () => {
  for (const [offset, value] of [[8, 12], [33, 0xffffffff], [33, 7], [41, 0]]) {
    const image = bytes(APNG);
    new DataView(image.buffer).setUint32(offset, value);
    assert.throws(() => checkImage(image.buffer), /Unsupported or damaged image/);
  }
});

test('duplicate or late animation control chunks are rejected as malformed PNG', () => {
  const image = bytes(APNG), control = image.slice(33, 53);
  const idat = Buffer.from(image).indexOf('IDAT') - 4;
  const afterIDAT = idat + 12 + new DataView(image.buffer).getUint32(idat);
  const duplicate = Uint8Array.from([...image.slice(0, 53), ...control, ...image.slice(53)]);
  const late = Uint8Array.from([...image.slice(0, 33), ...image.slice(53, afterIDAT), ...control, ...image.slice(afterIDAT)]);
  for (const malformed of [duplicate, late])
    assert.throws(() => checkImage(malformed.buffer), /Unsupported or damaged image/);
});

test('a damaged PNG signature is not accepted as a still image', () => {
  const image = bytes(PNG);
  image[4] = 0;
  assert.throws(() => checkImage(image.buffer), /Unsupported or damaged image/);
});
